    (N'a.hamdan2', N'INV-5350', N'RCPT-9313', N'PAYMENT', -3512.00, CAST('2023-08-22T00:00:00' AS DATETIME2)),
    (N'a.hamdan2', N'INV-5350', NULL, N'CHARGE', 3512.00, CAST('2023-08-15T09:00:00' AS DATETIME2))
) AS v(username, invno, receipt, ttype, amount, tdate)
JOIN dbo.users u ON u.username = v.username
JOIN dbo.students st ON st.user_id = u.user_id
JOIN dbo.student_invoices inv ON inv.invoice_number = v.invno
LEFT JOIN dbo.payments pay ON pay.receipt_number = v.receipt;

COMMIT TRANSACTION;
PRINT N'>>> SEED 08 (finance) completed.';
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
